text:
{ code: "E_AUTH", family: "auth",
  message: "the session changed before this journaled write was admitted", site: "client.mutate",
  rewrite: "restore the current app session; submit again only if the write is still intended", guide: "writes" }

{ code: "E_STORE_REPLACED", family: "store",
      message: "the intent belongs to a different or unprovable store; whether it executed is unknown; do not retry automatically",
      site: "app.mutate", rewrite: "reconcile this write with its original store before submitting new intent", guide: "sync" }

{ code: "E_CLIENT", family: "client", site: "app.mutate",
        message: "The online write journal was damaged or belonged to another owner; its bytes were preserved and no saved intent was replayed.",
        rewrite: `inspect the saved bytes with await sessionStore.get(${JSON.stringify(side)}); submit new intent with app.mutate(op, args)` }

{ code: "E_CLIENT", family: "client", site: "app.mutate",
        message: "The damaged online write journal could not be preserved; its original bytes remain and writes are blocked until storage is repaired.",
        rewrite: "repair sessionStore, then reopen createApp({ url, sessionStore })" }

{ code: "E_CLIENT", family: "client", site: "app.auth",
    message: "the saved session retirement record is damaged or belongs to another backend",
    rewrite: "repair sessionStore, then createApp({ url, sessionStore })" }

{ code, family: "store", site: "client", guide: "sync",
      message: `${code === "E_STORE_REPLACED" ? "the backend store identity changed" : "the backend store sequence regressed"}; outstanding writes may have executed and their outcomes are unknown; this client will not retry them`,
      rewrite: "close this client and create a new client for the current backend; reconcile outstanding writes before submitting new intent" }

{
      code: "E_STORE", family: "store", site: "client.residency",
      message: `cannot read device residency: ${String(error)}`,
      rewrite: "restart the failed device host and reopen the client, then retry client.residency()",
      guide: "residency",
    }

{ code: "E_CLIENT", family: "store", site: "app.auth",
  message: `session authority could not be committed or read: ${String(error)}`,
  rewrite: "restore writable IndexedDB and localStorage, then retry app.auth.login", guide: "writes" }

{
        code: write.why.code, family: write.why.family, message: `write refused: ${write.why.code}; whether it executed is unknown; do not retry automatically`,
      }

{
                    code: write.why.code, family: write.why.family,
                    message: `write refused: ${write.why.code}; whether it executed is unknown; do not retry automatically`,
                  }
